using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Reflection;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using UnityEngine.Networking;
using CatCafePreview.Standalone;
namespace CatCafePreview
{
    public sealed class StandalonePatronConversationSmoke:MonoBehaviour
    {
        static int checks;string output;static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
        static readonly string[] Destinations={"patron_visit","patron_moody_visit","patron_strict_visit"};
        static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
        public static LocalCafeBackend Create(string path)
        {var r=StandaloneEncounterConversationSmoke.Rules();r.starting_funds=20000;r.max_probability=0;r.growth.threshold=1;r.intake.day=r.regular_introduction.day=9999;r.dispatch_unlocks=new DispatchUnlockRule[0];return new LocalCafeBackend(path,r);}
        static void Good(LocalCafeBackend b,string kind,string choice=null,string cat="cat-sora",int slot=1){if((kind=="day_off" || kind=="dispatch_patron") && b.Simulation.State.phase=="closed"){Grow(b);StandaloneDispatchConversationSmoke.Good(b,"next_day");}StandaloneDispatchConversationSmoke.Good(b,kind,choice,cat,slot);}
        public static void Finish(LocalCafeBackend b){var row=b.DispatchConversation;row.Current.node=CafeDispatchDialogue.Lines(row.stage,row.Current.branch_id,"",row.Destination).Length;row.Current.page_offset=0;CafeDispatchDialogue.Finish(row);b.DispatchConversationOpen=false;}
        static void Start(LocalCafeBackend b,string cat,string destination){if(b.Simulation.State.phase=="closed"){Grow(b);Good(b,"next_day");}b.BeginDispatchDeparture(cat,destination);}
        static void Grow(LocalCafeBackend b){while(b.View().growth_choices.Length>0){var g=b.View().growth_choices[0];Good(b,g.kind,g.kind=="resolve_growth"?"service":g.choices[0].choice,g.cat_id);}}
        static void Old(LocalCafeBackend b,string path,int source,int slot){var save=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-"+source+".json")));save.slot=slot;save.dispatch_conversations=null;save.dispatch_conversation_selected=null;File.WriteAllText(Path.Combine(path,"slot-"+slot+".json"),JsonUtility.ToJson(save));Good(b,"load_game",slot:slot);}
        public static int BackendChecks(string folder,bool restart)
        {
            checks=0;
            foreach(string destination in Destinations)foreach(bool matched in new[]{false,true})
            {
                string path=Path.Combine(folder,destination+matched);var b=Create(path);
                if(restart)foreach(int slot in new[]{1,2,3,4,5,6,7}){Good(b,"load_game",slot:slot);Check(b.DispatchConversation!=null,"Process restore lost conversation "+slot);CafeDispatchDialogue.Validate(b.DispatchConversations,b.DispatchConversationSelected,b.Simulation.State);}
                Good(b,"new_game","patron");if(matched){Good(b,"day_off");Grow(b);Good(b,"next_day");}
                string cat=matched?"cat-sora":"cat-tama";
                Start(b,cat,destination);b.DispatchConversation.Current.node=1;b.DispatchConversation.Current.page_offset=2;Good(b,"save_game",slot:1);Good(b,"load_game",slot:1);Check(b.DispatchConversation.Current.page_offset==2,"Page position lost");
                var c=b.Simulation.State.cats.Single(x=>x.id==cat);c.fatigue=40.1;Check(!b.View().patron_dispatch.options.Single(o=>o.cat_id==cat && o.choice==destination).can_select,"Fatigue shortage accepted");c.fatigue=0;
                var row=b.DispatchConversation;row.Current.branch_id="cancelled";Finish(b);Good(b,"save_game",slot:2);Start(b,cat,destination);Check(row.Current.viewed_branches.SequenceEqual(new[]{"cancelled"}),"Cancel record lost");
                var option=b.View().patron_dispatch.options.Single(o=>o.cat_id==cat && o.choice==destination);double funds=b.Simulation.State.funds;
                string payload=StandaloneDispatchConversationSmoke.Payload(b,"dispatch_patron",destination,cat);var response=StandaloneDispatchConversationSmoke.Raw(b,payload);Check(response.result==UnityWebRequest.Result.Success,"Departure failed "+response.error);string after=JsonUtility.ToJson(b.Simulation.State);StandaloneDispatchConversationSmoke.Raw(b,payload);Check(after==JsonUtility.ToJson(b.Simulation.State),"Repeated departure changed simulation");
                Check(row.Current.branch_id=="departed" && b.Simulation.State.funds==funds,"Departure did not fix state");Good(b,"save_game",slot:3);Finish(b);var ev=b.Simulation.State.dispatches.Single();string fixedTerms=b.PatronFixedTerms(ev);Check(option.reward==ev.reward && option.satisfaction==b.Simulation.PatronEventGain(ev),"Preview differs from departure");Check(ev.patron_match==null || ev.patron_match.matched==matched,"Match fixture wrong");
                Check(b.BeginDispatchEvent(ev.id),"Optional travel absent");Finish(b);Check(!b.DispatchResultPending && !b.ConversationBlocksProgress,"Optional reading blocks progression");Good(b,"save_game",slot:4);Old(b,path,4,8);Check(b.BeginDispatchEvent(ev.id) && b.DispatchConversation.departure==null,"Old travelling invented departure");Good(b,"load_game",slot:4);
                while(ev.remaining>0){Grow(b);Good(b,"day_off");ev=b.Simulation.State.dispatches.Single();}
                b.PrepareDispatchConversation();Check(b.DispatchConversation.stage=="return" && b.PatronFixedTerms(ev)==fixedTerms,"Return rejudged terms");Good(b,"save_game",slot:5);Old(b,path,5,8);Check(b.BeginDispatchEvent(ev.id) && b.DispatchConversation.departure==null,"Old waiting invented viewing");Good(b,"load_game",slot:5);ev=b.Simulation.State.dispatches.Single();funds=b.Simulation.State.funds;
                payload=StandaloneDispatchConversationSmoke.Payload(b,"receive_patron",ev.id,cat);response=StandaloneDispatchConversationSmoke.Raw(b,payload);Check(response.result==UnityWebRequest.Result.Success,"Receipt failed "+response.error);after=JsonUtility.ToJson(b.Simulation.State);StandaloneDispatchConversationSmoke.Raw(b,payload);StandaloneDispatchConversationSmoke.Send(b,"receive_patron",ev.id,cat);Check(after==JsonUtility.ToJson(b.Simulation.State) && b.Simulation.State.funds==funds+ev.reward,"Duplicate receipt");
                Check(b.DispatchConversation.Current.branch_id=="received" && b.DispatchResultPending && b.PatronFixedTerms(ev)==fixedTerms,"Receipt lost result");Check(destination!="patron_strict_visit" || matched || b.Simulation.State.patron.members.Single(x=>x.id==destination).value==0,"Strict mismatch gained");
                Good(b,"save_game",slot:6);var fresh=Create(path);Good(fresh,"load_game",slot:6);Check(fresh.DispatchResultPending && fresh.DispatchConversation.Current.branch_id=="received","Fresh result lost");Finish(b);Good(b,"save_game",slot:7);b.RememberViewedConversations();Check(string.IsNullOrEmpty(b.ReplayImportNotice),"Extra import failed "+b.ReplayImportNotice);Check(b.Replays.Load().entries.Count(e=>e.conversation_id.StartsWith(CafeDispatchDialogue.ConversationId(destination)))==4,"Extra branches missing");after=JsonUtility.ToJson(b.Simulation.State);b.ImportViewedSaves();Check(after==JsonUtility.ToJson(b.Simulation.State),"Archive changed state");Old(b,path,7,9);Check(!b.BeginDispatchEvent(ev.id) && b.DispatchConversations.Length==0,"Old receipt invented viewing");Good(b,"load_game",slot:7);Grow(b);
                // A later trip keeps a distinct case and the moody wish advances only after receipt.
                if(b.Simulation.State.phase=="closed")Good(b,"next_day");
                Start(b,cat,destination);Good(b,"dispatch_patron",destination,cat);Check(b.DispatchConversations.Length==2,"Repeat visit overwrote case");if(destination=="patron_moody_visit")Check(b.Simulation.State.dispatches.Last().patron_match.condition_index==1 && b.PatronFixedTerms(b.Simulation.State.dispatches.First())==fixedTerms,"Wish change modified old visit");
            }
            var multi=Create(Path.Combine(folder,"parallel"));Good(multi,"new_game","patron");int i=0;foreach(string d in Destinations){string cat=new[]{"cat-sora","cat-tama","cat-mike"}[i++];Start(multi,cat,d);Good(multi,"dispatch_patron",d,cat);Finish(multi);}Good(multi,"day_off");Grow(multi);Good(multi,"day_off");Check(multi.Simulation.State.dispatches.Count(e=>e.status=="waiting")==3,"Parallel visits lost");foreach(var ev in multi.Simulation.State.dispatches.ToArray()){Check(multi.BeginDispatchEvent(ev.id),"Parallel return absent");Good(multi,"receive_patron",ev.id,ev.cat_id);Finish(multi);}Check(!multi.DispatchResultPending && !multi.Simulation.DispatchWaiting,"Parallel results stranded");
            var final=StandalonePatronEndingSmoke.Create(Path.Combine(folder,"final"));Good(final,"new_game","patron");foreach(string d in Destinations){Start(final,"cat-tama",d);Good(final,"dispatch_patron",d,"cat-tama");Finish(final);Good(final,"day_off");final.PrepareDispatchConversation();Good(final,"receive_patron",final.DispatchConversation.DispatchId,"cat-tama");Check(final.DispatchResultPending,"Final result absent");if(d==Destinations.Last())Check(final.Simulation.PatronWaiting && final.PatronEndingPending && final.Simulation.State.clear_results.Count==1,"Final receipt did not fix clear");Check(final.Simulation.State.patron.satisfaction<=final.Simulation.Rules.patron.target,"Satisfaction exceeded cap");Check(StandaloneDispatchConversationSmoke.Send(final,"continue_patron").result!=UnityWebRequest.Result.Success,"Pending return continued goal");Finish(final);}Check(!final.DispatchResultPending && final.PatronEndingPending,"Ending did not follow return");Good(final,"save_game",slot:1);var restored=StandalonePatronEndingSmoke.Create(Path.Combine(folder,"final"));Good(restored,"load_game");Check(restored.PatronEndingPending && restored.Simulation.State.clear_results.Count==1,"Final save duplicated clear");
            return checks;
        }
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--catcafe-patron-conversation-check");if(i<0)return;var qa=new GameObject("Patron conversation verification").AddComponent<StandalonePatronConversationSmoke>();DontDestroyOnLoad(qa);qa.output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(qa.output);Application.runInBackground=true;try{int n=BackendChecks(Path.Combine(qa.output,"cases"),args.Contains("--patron-conversation-restart"));File.WriteAllText(Path.Combine(qa.output,"backend-result.txt"),"PASS: "+n);qa.StartCoroutine(qa.Guard());}catch(Exception e){qa.Fail(e);}}
        void Fail(Exception e){File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(1);}
        IEnumerator Guard(){var r=Run();while(true){bool more;try{more=r.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return r.Current;}}
        IEnumerator Run()
        {
            SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var client=FindObjectOfType<PythonStateClient>();var owner=client.GetComponent<PythonDispatchPanel>();var ui=owner.Dialogue;
            foreach(string destination in Destinations)
            {
                var b=Create(Path.Combine(output,"ui-"+destination));CafeBackends.UseLocal(b);Good(b,"new_game","patron");Apply(client,b);yield return null;owner.OpenOption("cat-tama",destination);owner.Send();yield return null;Check(ui.Showing && !owner.panel.activeSelf,"Patron UI entry absent");b.DispatchConversation.Current.node=4;Apply(client,b);yield return null;
                ui.Answer(false);ui.Answer(true);yield return null;Check(b.Simulation.State.dispatches.Count==0 && b.DispatchConversation.Current.branch_id=="cancelled","Cancel double click departed");Finish(b);ui.Close();owner.OpenOption("cat-tama",destination);owner.Send();b.DispatchConversation.Current.node=4;Apply(client,b);yield return null;ui.Answer(true);ui.Answer(true);yield return new WaitForSecondsRealtime(.3f);Check(b.Simulation.State.dispatches.Count==1,"Repeated UI departure");Finish(b);ui.Close();Apply(client,b);yield return null;
                var ev=b.Simulation.State.dispatches.Single();owner.OpenReturn(ev.id);yield return null;Check(ui.Showing && b.DispatchConversation.stage=="travelling","Optional UI missing");ui.Close();Check(!b.ConversationBlocksProgress,"Optional closed UI blocks");Good(b,"day_off");Grow(b);Good(b,"day_off");Apply(client,b);yield return null;client.GetComponent<PythonEventListPanel>().ShowMenu(6);yield return null;Check(ui.Showing && b.DispatchConversation.stage=="return","Return list route missing");b.DispatchConversation.Current.node=3;Apply(client,b);yield return null;ui.Answer(false);yield return null;Check(b.Simulation.DispatchWaiting && !ui.Showing,"Postpone received");owner.OpenReturn(ev.id);yield return null;double funds=b.Simulation.State.funds;ui.Answer(true);ui.Answer(true);yield return new WaitForSecondsRealtime(.3f);Check(b.DispatchResultPending && b.Simulation.State.funds==funds+ev.reward,"UI receipt duplicated");Check(!client.GetComponent<PythonGrowthPanel>().panel.activeSelf,"Growth covered return");ui.Close();client.GetComponent<PythonEventListPanel>().ShowMenu(6);yield return null;Check(ui.Showing,"Closed return cannot resume");
                b.DispatchConversation.Current.node=2;Apply(client,b);typeof(AcquisitionConversationPanel).GetField("revealed",Hidden).SetValue(ui,10000f);ui.Refresh();Canvas.ForceUpdateCanvases();var body=(Text)typeof(AcquisitionConversationPanel).GetField("body",Hidden).GetValue(ui);Check(body.cachedTextGenerator.lineCount<=3,"More than three lines");ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;Check(ui.HistoryScroll.content.rect.height>=ui.HistoryScroll.content.GetComponent<Text>().preferredHeight-1,"Backlog clipped");ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;
                Good(b,"save_game",slot:1);Finish(b);ui.Close();Apply(client,b);yield return null;Check(!b.DispatchResultPending && client.GetComponent<PythonGrowthPanel>().panel.activeSelf,"Growth did not follow result");
            }
            var final=StandalonePatronEndingSmoke.Create(Path.Combine(output,"final-ui"));CafeBackends.UseLocal(final);Good(final,"new_game","patron");
            foreach(string d in Destinations){Start(final,"cat-tama",d);Good(final,"dispatch_patron",d,"cat-tama");Finish(final);Good(final,"day_off");final.PrepareDispatchConversation();Good(final,"receive_patron",final.DispatchConversation.DispatchId,"cat-tama");if(d!=Destinations.Last())Finish(final);}
            Apply(client,final);yield return null;Check(client.GetComponent<PopularityEndingPanel>()?.Showing!=true && !client.GetComponent<PythonGoalPanel>().panel.activeSelf,"Ending covered final receipt");client.GetComponent<PythonEventListPanel>().ShowMenu(6);yield return null;Check(ui.Showing,"Final return cannot resume");ui.Close();client.GetComponent<PythonEventListPanel>().ShowMenu(6);yield return null;Check(ui.Showing && final.Simulation.State.clear_results.Count==1,"Final return resumed ending twice");Finish(final);ui.Close();Apply(client,final);yield return null;Check(client.GetComponent<PopularityEndingPanel>().Showing && final.Simulation.State.clear_results.Count==1,"Ending did not follow final result");
            File.WriteAllText(Path.Combine(output,"result.txt"),"PASS: "+checks+" patron conversation checks");
            client.GetComponent<PopularityEndingPanel>().Close();
            // Leave a dedicated short fixture ready for real desktop review, without touching normal saves.
            var manual=Create(Path.Combine(output,"manual"));CafeBackends.UseLocal(manual);Good(manual,"new_game","patron");Start(manual,"cat-tama","patron_strict_visit");Good(manual,"dispatch_patron","patron_strict_visit","cat-tama");Finish(manual);Good(manual,"day_off");Grow(manual);Good(manual,"day_off");manual.PrepareDispatchConversation();manual.DispatchConversation.Current.node=3;Good(manual,"save_game",slot:1);Apply(client,manual);yield return null;owner.OpenReturn(manual.DispatchConversation.DispatchId);

        }
        static void Apply(PythonStateClient client,LocalCafeBackend b){typeof(PythonStateClient).GetMethod("Accept",Hidden).Invoke(client,new object[]{b.View()});Canvas.ForceUpdateCanvases();}
    }
